import java.util.*

fun main() {
    val board = Array(4) { IntArray(4) }
    val scanner = Scanner(System.`in`)

    for (i in 0 until 4) {
        for (j in 0 until 4) {
            val c = scanner.next()[0]
            board[i][j] = when (c) {
                'x' -> 1
                'o' -> -3
                else -> 0
            }
        }
    }

    var canWin = false
    var i = 0
    while (!canWin && i < 4) {
        for (j in 0 until 4) {
            if (board[i][j] >= 0) {
                var sumHor = 0
                var sumDiaUp = 0
                var sumDiaDown = 0
                var sumVer = 0

                if (j < 2)
                    sumHor = board[i][j] + board[i][j + 1] + board[i][j + 2]
                if (i < 2)
                    sumVer = board[i][j] + board[i + 1][j] + board[i + 2][j]
                if (i < 2 && j < 2)
                    sumDiaUp = board[i][j] + board[i + 1][j + 1] + board[i + 2][j + 2]
                if (i >= 2 && j < 2)
                    sumDiaDown = board[i][j] + board[i - 1][j + 1] + board[i - 2][j + 2]

                if (sumHor == 2 || sumDiaUp == 2 || sumDiaDown == 2 || sumVer == 2) {
                    canWin = true
                    break
                }
            }
        }
        i++
    }

    if (canWin)
        println("YES")
    else
        println("NO")
}

